# Build full pattern from tiles: normalize components of color 2 relative to the smallest bounding box covering all comps
def analyze(g):
    H,W=len(g),len(g[0])
    comps=[]; seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and (i,j) not in seen:
                st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==2 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                comps.append(comp)
    # bounding box over all 2-cells
    rs=[r for c in comps for r,_ in c]; cs=[c2 for c in comps for _,c2 in c]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    hgt=h_=r1-r0+1; wid=c1-c0+1
    P=[[0]*wid for _ in range(hgt)]
    for cp in comps:
        for r,c in cp: P[r-r0][c-c0]=2
    return g,h_,wid,P,(r0,c0)
