            if a<b:
                d=(b[0]-a[0],b[1]-a[1])
                if d: cand[d]+=1
    for d,v in sorted(cand.items(),key=lambda kv:-kv[1]):
        if b1 is None: b1=d
        elif b1[0]*d[1]!=b1[1]*d[0]: b2=d; break
    pts=set(origins)
    changed=True
    while changed:
        changed=False
        for p in list(pts):
            for v in [b1,b2,(-b1[0],-b1[1]),(-b2[0],-b2[1])]:
                q=(p[0]+v[0],p[1]+v[1])
                if 0<=q[0]<len(inp) and 0<=q[1]<len(inp[0]):
                    pts.add(q); changed=True
    hits=[[0]*len(inp[0]) for _ in range(len(inp))]
    for (pr,pc) in pts:
        for dr,dc in info[0][2]:
            r_,c_=pr+dr,pc+dc
            if 0<=r_<len(inp) and 0<=c_<len(inp[0]):
